\begin{figure}[ht]
\centering
\includegraphics[width=\linewidth]{images/paper_grid_figure.pdf}
\caption{
  \textbf{ODE trajectory evolution across training iterations}
  (Colour MNIST-RGB \emph{simple} experiment).
  \emph{Columns} (left $\to$ right): forward model at different
  training iterations (Initial $\to$ Final).
  \emph{Rows} (top $\to$ bottom): ODE time $t$ from source ($t{=}0$)
  to transported image ($t{=}1$), integrated with 200 Euler steps.
  The same PURPLE digit-7 source is used in every column.
  Adaptation progressively tilts the transport from the wrong
  colour (dark-blue at iteration~0) toward the correct CYAN target,
  demonstrating cost-free transfer of the cyclic channel-permutation law.}
\label{fig:color_grid}
\end{figure}

